# stripc.py: remove the comments of the C files that patsopt generates (run by mkboot.sh).
#
# patsopt writes a comment for every instruction (`emit_instr: loc0 = <absolute path>..`), template instance,
# `letpush`, ...: 55-60% of the bytes of the generated C code, with the absolute path of the build directory.
# The comments are removed, except the first one of a file (the "generated by" banner).  The C lexical structure is
# respected: comment markers inside string and character literals are kept.  A comment becomes one space (so that the
# tokens around it do not merge); the lines that are empty after that are dropped, so that the preprocessor
# directives (which need a line of their own) and the line continuations are untouched.
# usage: stripc.py file.c ...   (the files are rewritten in place)
import os, re, sys

TOK = re.compile(r'''"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|/\*.*?\*/|//[^\n]*(?:\\\n[^\n]*)*''', re.S)

def strip(src):
    first = [True]
    def sub(m):
        t = m.group(0)
        if t[0] in '"\'':
            return t
        if first[0] and t.startswith('/*'):
            first[0] = False
            return t
        return ' '
    out = TOK.sub(sub, src)
    # an empty line after a line continuation (`\`) is kept: dropping it would join the next line to a #define
    res = []; cont = False
    for l in out.split('\n'):
        l = l.rstrip()
        if l or cont:
            res.append(l + '\n')
        cont = l.endswith('\\')
    return ''.join(res)

for f in sys.argv[1:]:
    with open(f, encoding='latin-1', newline='') as fh:
        s = fh.read()
    with open(f + '.tmp', 'w', encoding='latin-1', newline='') as fh:
        fh.write(strip(s))
    os.replace(f + '.tmp', f)
